/* Discover Sharm — admin / owner consoles: service worker.  Generated by tools/build.mjs (the version below changes with every build).
 *  - the console shell (pages, css, js, icons) is pre-cached, so the installed app opens instantly and shows its own screen even when offline
 *  - pages: network first (always the newest build, sign-in state is read by the page itself), cached copy when the network is slow/offline
 *  - versioned /console/* and /icons/* assets: cache first · Google Fonts: stale-while-revalidate
 *  - Supabase, the Workers (content / settings / translate / media) and every non-GET request are never touched or cached
 */
const VERSION = '__VERSION__';
const SHELL = 'dsc-shell-' + VERSION;
const RUNTIME = 'dsc-runtime-v1';
const PRECACHE = __PRECACHE__;
const NAV_TIMEOUT = 3500;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL);
    await Promise.allSettled(PRECACHE.map((u) => cache.add(new Request(u, { cache: 'reload' }))));
    await self.skipWaiting();
  })());
});
self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('dsc-') && k !== SHELL && k !== RUNTIME) await caches.delete(k);
    await self.clients.claim();
  })());
});

const FONT_HOSTS = ['fonts.googleapis.com', 'fonts.gstatic.com'];
self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) {
    if (FONT_HOSTS.includes(url.hostname)) event.respondWith(staleWhileRevalidate(req));
    return;                                                   // Supabase / Workers / Google sign-in: straight to the network
  }
  if (req.mode === 'navigate') { event.respondWith(page(req)); return; }
  if (url.pathname.startsWith('/console/') || url.pathname.startsWith('/icons/') || url.pathname === '/manifest.webmanifest') event.respondWith(cacheFirst(req));
});

async function page(req) {
  const url = new URL(req.url);
  const key = url.pathname === '/' ? '/' : url.pathname;     // ignore ?query / #hash (recovery links, utm)
  try {
    const res = await Promise.race([fetch(req), new Promise((_, rej) => setTimeout(() => rej(new Error('slow')), NAV_TIMEOUT))]);
    if (res && res.ok && res.type === 'basic') (await caches.open(SHELL)).put(key, res.clone());
    return res;
  } catch (e) {
    const hit = (await caches.match(key, { cacheName: SHELL })) || (await caches.match('/', { cacheName: SHELL }));
    return hit || new Response('<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><body style="font-family:system-ui;text-align:center;padding:48px 20px;background:#f6f5f3;color:#16171b"><h2>لا يوجد اتصال بالإنترنت</h2><p>No internet connection — try again when you are back online.</p>', { headers: { 'Content-Type': 'text/html; charset=utf-8' }, status: 503 });
  }
}
async function cacheFirst(req) {
  const hit = await caches.match(req, { ignoreVary: true });
  if (hit) return hit;
  const res = await fetch(req);
  if (res && res.ok && res.type === 'basic') (await caches.open(SHELL)).put(req, res.clone());
  return res;
}
async function staleWhileRevalidate(req) {
  const cache = await caches.open(RUNTIME);
  const hit = await cache.match(req);
  const net = fetch(req).then((res) => { if (res && (res.ok || res.type === 'opaque')) cache.put(req, res.clone()); return res; }).catch(() => hit);
  return hit || net;
}
